def icon(name: str, cls: str = "") -> Markup:
    if name not in ICONS:  # a missing icon must never break a page
        log.warning("Unknown icon %r", name)
    return Markup(f'<svg class="i {cls}" viewBox="0 0 24 24" aria-hidden="true">{ICONS.get(name, "")}</svg>')


def band(score: float | None) -> str:
    """Colour class for a 1-10 score."""
    if score is None:
        return "none"
    return "hi" if score >= 8 else "mid" if score >= 6 else "lo"


def local_time(dt: datetime | None, fmt: str = "%d.%m.%Y %H:%M") -> str:
    """Dates are stored in UTC and shown in Tashkent time."""
    return dt.astimezone(ZoneInfo("Asia/Tashkent")).strftime(fmt) if dt else "—"


templates.env.globals.update(icon=icon, band=band, local_time=local_time)
